    def chain_construct():
        """Key-chain decomposition with priority-merge construction.

        For each key, collect the transactions touching it (its conflict
        chain). Build a global sequence by ready-set simulation: at each
        step, score every unplaced transaction by the total hotness of
        keys it shares with unplaced earlier-chain transactions, and
        place the transaction that is 'most ready' (lowest blocking
        score), with randomized tie-breaking for restart diversity.
        """
        keys_of = {}
        key_txns = {}
        for t in range(n):
            ks = set()
            ops = workload.txns[t] if hasattr(workload, 'txns') else []
            for op in ops:
                ks.add(op[1] if isinstance(op, (list, tuple)) else str(op).split('-')[-1])
            keys_of[t] = ks
            for k in ks:
                key_txns.setdefault(k, []).append(t)
        key_hot = {k: len(v) for k, v in key_txns.items()}
        # per-key chain order: transactions sorted by total conflict load
        load = {}
        for t in range(n):
            load[t] = sum(key_hot[k] for k in keys_of[t])
        chains = {}
        for k, ts in key_txns.items():
            chains[k] = sorted(ts, key=lambda t: -load[t])
        pos_in_chain = {}
        for k, order in chains.items():
            for idx, t in enumerate(order):
                pos_in_chain.setdefault(t, {})[k] = idx
        placed = set()
        seq = []
        # blocking score: hotness of keys where txn still has earlier
        # unplaced chain predecessors (i.e., it is not yet 'ready')
        while len(placed) < n:
            best_t, best_s = None, None
            cands = []
            for t in range(n):
                if t in placed:
                    continue
                s = 0
                for k, idx in pos_in_chain.get(t, {}).items():
                    for j in range(idx):
                        if chains[k][j] not in placed:
                            s += key_hot[k]
                            break
                cands.append((s, t))
            min_s = min(c for c, _ in cands)
            pool = [t for c, t in cands if c <= min_s + 1e-9]
            t = random.choice(pool)
            seq.append(t)
            placed.add(t)
        return seq

